// Browser adapter for locally compiled Rust support lattice. No remote code.
// Wire projection is generated by the local verified evidence-session engine.
import {SUPPORT_WASM_SHA256} from './generated-support-pin.js';
const INVALID=0xffffffff;
let loaded;
async function load(){
 if(!loaded)loaded=(async()=>{
  const url=new URL('./support-lattice.wasm',document.baseURI);
  if(url.origin!==location.origin)throw Error('SUPPORT_ORIGIN');
  const response=await fetch(url,{credentials:'omit',redirect:'error',referrerPolicy:'no-referrer'});
  if(!response.ok)throw Error('SUPPORT_MODULE_UNAVAILABLE');
  const size=Number(response.headers.get('content-length'));
  if(size>1048576)throw Error('SUPPORT_MODULE_SIZE');
  if(!response.body)throw Error('SUPPORT_MODULE_BODY');
  const reader=response.body.getReader(),chunks=[];
  let length=0;
  try{
   for(;;){
    const {done,value}=await reader.read();
    if(done)break;
    length+=value.byteLength;
    if(length>1048576){await reader.cancel();throw Error('SUPPORT_MODULE_SIZE');}
    chunks.push(value);
   }
  }finally{reader.releaseLock();}
  const bytes=new Uint8Array(length);let offset=0;
  for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.byteLength;}
  const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');
  if(hash!==SUPPORT_WASM_SHA256)throw Error('SUPPORT_MODULE_DIGEST');
  const module=await WebAssembly.compile(bytes);
  if(WebAssembly.Module.imports(module).length)throw Error('SUPPORT_MODULE_IMPORTS');
  const instance=await WebAssembly.instantiate(module,{});
  if(typeof instance.exports.support_analyze!=='function'||typeof instance.exports.support_read!=='function')throw Error('SUPPORT_ABI');
  return instance.exports;
 })().catch(e=>{loaded=undefined;throw e;});
 return loaded;
}
const ID=/^[A-Za-z][A-Za-z0-9_-]{0,63}$/;
const decisions=['constraint_satisfied','constraint_refuted','blocked','incompatible','indeterminate'];
function validIds(xs){return xs.every((x,i)=>ID.test(x.id)&&(!i||xs[i-1].id<x.id));}
export async function analyzeSupport(projection, budget=256){
 if(projection?.version!==1||!Array.isArray(projection.worlds)||!Array.isArray(projection.observations)||
 projection.worlds.length<1||projection.worlds.length>12||projection.observations.length>8||
 !validIds(projection.worlds)||!validIds(projection.observations)||!Number.isInteger(budget)||budget<0||budget>256)throw Error('SUPPORT_PROJECTION');
 const {worlds,observations}=projection,all=(1<<worlds.length)-1;
 let sat=0,no=0,low=0n,high=0n;
 worlds.forEach((w,i)=>{
  if(!decisions.includes(w.decision))throw Error('SUPPORT_DECISION');
  if(w.decision==='constraint_satisfied')sat|=1<<i;
  if(w.decision==='constraint_refuted')no|=1<<i;
 });
 observations.forEach((o,i)=>{
  if(!Number.isInteger(o.mask)||o.mask<0||o.mask>all)throw Error('SUPPORT_MASK');
  if(i<4)low|=BigInt(o.mask)<<BigInt(12*i);else high|=BigInt(o.mask)<<BigInt(12*(i-4));
 });
 const wasm=await load();
 // No await between invocation and scalar reads: one browser-thread transaction.
 if((wasm.support_analyze(worlds.length,observations.length,sat,no,low,high,budget)>>>0)!==0)throw Error('SUPPORT_REFUSED');
 const read=(field,index=0)=>wasm.support_read(field,index)>>>0;
 const names=(xs,mask)=>xs.filter((_,i)=>mask&(1<<i)).map(x=>x.id);
 const family=(count,field)=>{
  const n=read(count);
  if(n>256)throw Error('SUPPORT_ABI_COUNT');
  return Array.from({length:n},(_,i)=>{
   const mask=read(field,i);
   if(mask>=(1<<observations.length))throw Error('SUPPORT_ABI_MASK');
   return names(observations,mask);
  });
 };
 const statuses=['conflict','satisfied','refuted','ambiguous','unresolved'];
 const state=read(0),alive=read(1),minimum=read(5);
 if(!statuses[state]||alive>all)throw Error('SUPPORT_ABI_STATE');
 return {version:1,engine:'rust-wasm-support/v1',current:statuses[state],survivingWorlds:names(worlds,alive),
  complete:read(2)===1,subsetsEvaluated:read(3),subsetsTotal:read(4),
  minimumConflictSize:minimum===INVALID?null:minimum,allMinimumConflictsComplete:read(6)===1,
  conflicts:family(7,10),satisfiedSupports:family(8,11),refutedSupports:family(9,12),
  qualification:'Conditional finite-model support only; inconsistent evidence cannot authorize a conclusion. Declared lineage does not establish independence.'};
}
